function gdSettingGet(string $key, string $default=''): string {
    try {
        db()->exec("CREATE TABLE IF NOT EXISTS app_settings (
            setting_key VARCHAR(190) PRIMARY KEY,
            setting_value MEDIUMTEXT NULL,
            updated_at DATETIME NOT NULL,
            updated_by VARCHAR(190) NULL
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $stmt=db()->prepare('SELECT setting_value FROM app_settings WHERE setting_key=:k LIMIT 1');
        $stmt->execute([':k'=>$key]);
        $value=$stmt->fetchColumn();
        return $value===false ? $default : (string)$value;
    } catch(Throwable $e) {
        error_log('[google-drive-sync] setting read failed: '.$e->getMessage());
        return $default;
    }
}

function gdB64url(string $data): string { return rtrim(strtr(base64_encode($data), '+/', '-_'), '='); }

function gdAccessToken(): string {
    static $token = null;
    if ($token !== null) return $token;
    $serviceJson = trim(env('GOOGLE_DRIVE_SERVICE_ACCOUNT_JSON', ''));
    if ($serviceJson !== '') {
        if (!str_starts_with($serviceJson, '{')) {
            $decoded = base64_decode($serviceJson, true);
            if ($decoded !== false) $serviceJson = $decoded;
        }
        $svc = json_decode($serviceJson, true);
        if (is_array($svc) && !empty($svc['client_email']) && !empty($svc['private_key'])) {
            $now = time();
            $header = gdB64url(json_encode(['alg'=>'RS256','typ'=>'JWT'], JSON_UNESCAPED_SLASHES));
            $claims = gdB64url(json_encode(['iss'=>$svc['client_email'],'scope'=>'https://www.googleapis.com/auth/drive','aud'=>'https://oauth2.googleapis.com/token','iat'=>$now,'exp'=>$now + 3500], JSON_UNESCAPED_SLASHES));
            $input = $header . '.' . $claims;$signature='';
            if (!openssl_sign($input, $signature, $svc['private_key'], OPENSSL_ALGO_SHA256)) apiError(503, 'Google-Drive-Servicekonto konnte nicht signieren.');
            $jwt=$input.'.'.gdB64url($signature);
            $resp=gdHttp('POST','https://oauth2.googleapis.com/token',['Content-Type: application/x-www-form-urlencoded'],http_build_query(['grant_type'=>'urn:ietf:params:oauth:grant-type:jwt-bearer','assertion'=>$jwt]),false);
            $body=json_decode($resp['body'],true);
            if ($resp['status']===200 && !empty($body['access_token'])) return $token=(string)$body['access_token'];
        }
    }
    $clientId=env('GOOGLE_DRIVE_CLIENT_ID',gdSettingGet('google_drive_client_id'));
    $clientSecret=env('GOOGLE_DRIVE_CLIENT_SECRET',gdSettingGet('google_drive_client_secret'));
    $refreshToken=env('GOOGLE_DRIVE_REFRESH_TOKEN',gdSettingGet('google_drive_refresh_token'));
    if ($clientId!=='' && $clientSecret!=='' && $refreshToken!=='') {
        $resp=gdHttp('POST','https://oauth2.googleapis.com/token',['Content-Type: application/x-www-form-urlencoded'],http_build_query(['client_id'=>$clientId,'client_secret'=>$clientSecret,'refresh_token'=>$refreshToken,'grant_type'=>'refresh_token']),false);
        $body=json_decode($resp['body'],true);
        if ($resp['status']===200 && !empty($body['access_token'])) return $token=(string)$body['access_token'];
    }
    apiError(503, 'Google Drive ist noch nicht verbunden. Bitte im Versicherungsportal „Mit Google Drive verbinden“ verwenden.');
}

function gdHttp(string $method,string $url,array $headers=[],?string $body=null,bool $auth=true): array {
    if ($auth) $headers[]='Authorization: Bearer '.gdAccessToken();
    $ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>$headers,CURLOPT_CONNECTTIMEOUT=>12,CURLOPT_TIMEOUT=>90,CURLOPT_FOLLOWLOCATION=>true]);
    if ($body!==null) curl_setopt($ch,CURLOPT_POSTFIELDS,$body);
    $response=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);
    if ($response===false || $err!=='') apiError(503,'Google-Drive-Verbindung fehlgeschlagen: '.($err?:'unbekannter Fehler'));
    return ['status'=>$status,'body'=>(string)$response];
}
function gdApi(string $method,string $path,array $query=[],?array $json=null): array {$url='https://www.googleapis.com/drive/v3/'.ltrim($path,'/');$query+=['supportsAllDrives'=>'true'];if($query)$url.='?'.http_build_query($query);$headers=[];$body=null;if($json!==null){$headers[]='Content-Type: application/json; charset=utf-8';$body=json_encode($json,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}$resp=gdHttp($method,$url,$headers,$body,true);$data=json_decode($resp['body'],true);if($resp['status']<200||$resp['status']>=300)apiError(503,'Google-Drive-API-Fehler ('.$resp['status'].').');return is_array($data)?$data:[];}
function gdFolderId(string $kind): string {return match($kind){'cases'=>env('GOOGLE_DRIVE_CASES_FOLDER_ID',DEFAULT_CASES_FOLDER_ID),'knowledge'=>env('GOOGLE_DRIVE_KNOWLEDGE_FOLDER_ID',DEFAULT_KNOWLEDGE_FOLDER_ID),'blanco'=>env('GOOGLE_DRIVE_BLANCO_FOLDER_ID',DEFAULT_BLANCO_FOLDER_ID),default=>''};}
function gdEscape(string $v): string{return str_replace("'","\\'",$v);}function gdListChildren(string $parentId,?string $mime=null,int $limit=1000):array{$q="'".gdEscape($parentId)."' in parents and trashed=false";if($mime!==null)$q.=" and mimeType='".gdEscape($mime)."'";$out=[];$pageToken='';do{$query=['q'=>$q,'fields'=>'nextPageToken,files(id,name,mimeType,modifiedTime,createdTime,size,webViewLink,parents,appProperties)','pageSize'=>min(1000,$limit-count($out)),'orderBy'=>'name_natural'];if($pageToken!=='')$query['pageToken']=$pageToken;$data=gdApi('GET','files',$query);foreach(($data['files']??[])as$f)$out[]=$f;$pageToken=(string)($data['nextPageToken']??'');}while($pageToken!==''&&count($out)<$limit);return$out;}
function gdFileMeta(string $fileId):array{return gdApi('GET','files/'.rawurlencode($fileId),['fields'=>'id,name,mimeType,parents,trashed']);}
function gdDownload(string $fileId):string{$resp=gdHttp('GET','https://www.googleapis.com/drive/v3/files/'.rawurlencode($fileId).'?alt=media&supportsAllDrives=true',[],null,true);if($resp['status']!==200)apiError(503,'Google-Drive-Datei konnte nicht geladen werden.');return$resp['body'];}
function gdCreateFolder(string $parentId,string $name):array{return gdApi('POST','files',['fields'=>'id,name,webViewLink'],['name'=>$name,'mimeType'=>'application/vnd.google-apps.folder','parents'=>[$parentId]]);}function gdFindChildByName(string $parentId,string $name):?array{$q="'".gdEscape($parentId)."' in parents and trashed=false and name='".gdEscape($name)."'";$data=gdApi('GET','files',['q'=>$q,'fields'=>'files(id,name,mimeType,modifiedTime,webViewLink)','pageSize'=>20]);return!empty($data['files'][0])?$data['files'][0]:null;}
function gdUserKey(array $user):string{return strtolower(trim((string)($user['email']??'')));}
