function gdUserCasesName(array $user):string{$name=trim((string)($user['full_name']??''));if($name===''){$local=explode('@',gdUserKey($user),2)[0]??'Benutzer';$name=preg_replace('/[^a-z0-9._-]+/i',' ',(string)$local)?:'Benutzer';}return'Schadenfälle '.$name;}
function gdUserCasesRoot(array $user):array{$legacy=gdFolderId('cases');if(!gdIsMarc($user)&&!gdIsHolger($user))return['id'=>$legacy,'name'=>'Schadenfälle Christian Wächter'];$meta=gdFileMeta($legacy);$parent=trim((string)(($meta['parents']??[])[0]??''));if($parent==='')apiError(503,'Der persönliche Schadenfälle-Ordner kann nicht angelegt werden: Übergeordneter Drive-Ordner fehlt.');$name=gdIsMarc($user)?'Schadenfälle Marc Schütt':'Schadenfälle Holger Roth';$folder=gdFindChildByName($parent,$name);if(!$folder||($folder['mimeType']??'')!=='application/vnd.google-apps.folder')$folder=gdCreateFolder($parent,$name);return['id'=>(string)$folder['id'],'name'=>$name];}
function gdEnsureKnownCasesRoots():void{$legacy=gdFolderId('cases');$meta=gdFileMeta($legacy);$parent=trim((string)(($meta['parents']??[])[0]??''));if($parent==='')return;foreach(['Schadenfälle Holger Roth','Schadenfälle Marc Schütt']as$name){$folder=gdFindChildByName($parent,$name);if(!$folder||($folder['mimeType']??'')!=='application/vnd.google-apps.folder')gdCreateFolder($parent,$name);}}
function gdAssertCaseAccess(string $caseId,array $user):void{if($caseId==='')apiError(400,'Kein aktiver Fallordner.');$root=gdUserCasesRoot($user);$folder=gdFileMeta($caseId);if(($folder['mimeType']??'')!=='application/vnd.google-apps.folder'||!in_array((string)$root['id'],$folder['parents']??[],true))apiError(403,'Dieser Schadenfall gehört zu einem anderen Benutzer und darf nicht geöffnet oder verändert werden.');registerCaseFolderOwner($caseId,$user,gdCaseMeta($caseId));}
function gdUploadJson(string $parentId,string $name,array $payload):array{$existing=gdFindChildByName($parentId,$name);$meta=['name'=>$name,'mimeType'=>'application/json'];if(!$existing)$meta['parents']=[$parentId];$boundary='svnet'.bin2hex(random_bytes(8));$body='--'.$boundary."\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n".json_encode($meta,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)."\r\n--".$boundary."\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n".json_encode($payload,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)."\r\n--".$boundary."--";$method=$existing?'PATCH':'POST';$url='https://www.googleapis.com/upload/drive/v3/files'.($existing?'/'.rawurlencode($existing['id']):'').'?uploadType=multipart&supportsAllDrives=true&fields=id,name,modifiedTime,webViewLink';$resp=gdHttp($method,$url,['Content-Type: multipart/related; boundary='.$boundary],$body,true);if($resp['status']<200||$resp['status']>=300)apiError(503,'Falldaten konnten nicht in Google Drive gespeichert werden.');return json_decode($resp['body'],true)?:[];}
function gdUploadBytes(string $parentId,string $name,string $mime,string $bytes):array{$meta=['name'=>$name,'mimeType'=>$mime,'parents'=>[$parentId]];$boundary='svnet'.bin2hex(random_bytes(8));$body='--'.$boundary."\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n".json_encode($meta,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)."\r\n--".$boundary."\r\nContent-Type: ".$mime."\r\n\r\n".$bytes."\r\n--".$boundary."--";$url='https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true&fields=id,name,mimeType,modifiedTime,webViewLink,webContentLink';$resp=gdHttp('POST',$url,['Content-Type: multipart/related; boundary='.$boundary],$body,true);if($resp['status']<200||$resp['status']>=300)apiError(503,'Dokument konnte nicht in Google Drive gespeichert werden.');return json_decode($resp['body'],true)?:[];}
function gdCaseFolders():array{return['01_Auftrag_Grundlagen','02_Fotos','03_Plaene_Technik','04_Rechnungen_KVA','05_Berichte_Nachtraege','06_Freigaben_Zahlungen','07_Korrespondenz','08_Abschluss'];}
function gdCaseCategory(string $name,string $mime=''):string{$n=gdNormalize($name);if(str_starts_with($mime,'image/')||preg_match('/\b(foto|fotos|bild|bilder|aufnahme|img|image)\b/u',$n))return'02_Fotos';if(preg_match('/\b(plan|plaene|zeichnung|technik|leckort|messprotokoll|trocknung|grundriss|statik)\b/u',$n))return'03_Plaene_Technik';if(preg_match('/\b(rechnung|abschlagsrechnung|teilrechnung|schlussrechnung|honorarrechnung|kva|kostenvoranschlag|kostenanschlag|schaetzung|angebot)\b/u',$n))return'04_Rechnungen_KVA';if(preg_match('/\b(abschluss|schlusserklaerung|schlussbericht|erledigt)\b/u',$n))return'08_Abschluss';if(preg_match('/\b(bericht|gutachten|nachtrag|stellungnahme|protokoll|dokumentenindex|rechnungsregister)\b/u',$n))return'05_Berichte_Nachtraege';if(preg_match('/\b(freigabe|zahlung|zahlungsbefuerwortung|vorauszahlung|abrechnung|entschaedigung)\b/u',$n))return'06_Freigaben_Zahlungen';if(preg_match('/\b(mail|email|e mail|brief|schreiben|korrespondenz|antwort|anfrage|rueckfrage)\b/u',$n)||in_array($mime,['message/rfc822','application/vnd.ms-outlook'],true))return'07_Korrespondenz';return'01_Auftrag_Grundlagen';}
function gdOriginalCaseName(string $name):string{return preg_replace('/^(?:Fallakte|Unterlage|Gutachten|KVA|Rechnung|Schriftverkehr|Mail)_\d{4}-\d{2}-\d{2}_\d{6}_(.+)$/u','$1',$name)??$name;}
function gdEnsureCaseFolder(string $caseId,string $name):array{$found=gdFindChildByName($caseId,$name);return$found&&($found['mimeType']??'')==='application/vnd.google-apps.folder'?$found:gdCreateFolder($caseId,$name);}
function gdExcludedCaseAsset(string $name,string $mime,string $bytes):?string{
    if(!str_starts_with(strtolower($mime),'image/'))return null;
    $hash=hash('sha256',$bytes);
    $knownHashes=[
        'd7e3662266444a6b1dd36cbb9a95546066eeae0d920a6f702ae716ba8aacb0cf',
        '102f119c25022500542ab12d312602666f7e210bfbe067170fa15b6a69899880',
        '008eabe9fac31bc3a22473dcd52b287630b8d7bdc4added8cd01aa47c73f9431',
        'a3ea5a503049dff4515211b7d41aba2f4e1ee33666df00a36a10fc862da3b1dc'
    ];
    if(in_array($hash,$knownHashes,true))return'Bekannte Signatur-, Profil- oder Systemgrafik';
    $normalized=gdNormalize($name);
    $knownNames=[
        'bvslogo2 7ce28f0c 700d 454c b645 db96d1c775fb',
        'chatgptimage9 aug 2026 19 01 28 4631f03f 1db8 414c a636 9b7ee544d6e1',
        'klein 353f6da3 e1b8 46b3 9797 b35ae37e31b4',
        'teams 32x32 9178119f 105b 4f5c abab a3ecadf7ea7c',
        'teams 32x32 91084020 9e25 41aa b1a1 6681281811c7'
    ];
    foreach($knownNames as$known)if(str_contains($normalized,$known))return'Bekannte Signatur-, Profil- oder Systemgrafik';
    return null;
}
function gdUploadCaseFile(string $folderId,string $name,string $mime,string $bytes,int $originalModified):array{$category=gdCaseCategory($name,$mime);$target=gdEnsureCaseFolder($folderId,$category);$targetId=(string)$target['id'];$size=strlen($bytes);foreach(gdListChildren($targetId,null,1000)as$item){if((string)($item['name']??'')!==$name||(int)($item['size']??-1)!==$size)continue;$saved=(int)($item['appProperties']['svOriginalModified']??0);if($saved===$originalModified)return['duplicate'=>true,'category'=>$category,'file'=>$item];}$meta=['name'=>$name,'mimeType'=>$mime,'parents'=>[$targetId],'appProperties'=>['svOriginalModified'=>(string)$originalModified]];$boundary='svnet'.bin2hex(random_bytes(8));$body='--'.$boundary."\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n".json_encode($meta,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)."\r\n--".$boundary."\r\nContent-Type: ".$mime."\r\n\r\n".$bytes."\r\n--".$boundary."--";$url='https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true&fields=id,name,mimeType,size,modifiedTime,webViewLink,webContentLink,appProperties';$resp=gdHttp('POST',$url,['Content-Type: multipart/related; boundary='.$boundary],$body,true);if($resp['status']<200||$resp['status']>=300)apiError(503,'Dokument konnte nicht in Google Drive gespeichert werden.');return['duplicate'=>false,'category'=>$category,'file'=>json_decode($resp['body'],true)?:[]];}
function gdOrganizeCase(string $caseId):array{$folders=[];foreach(gdCaseFolders()as$name){$f=gdEnsureCaseFolder($caseId,$name);$folders[$name]=(string)$f['id'];}$moved=0;$ignored=0;foreach(gdListChildren($caseId,null,1000)as$file){if(($file['mimeType']??'')==='application/vnd.google-apps.folder'||in_array((string)($file['name']??''),[CASE_META_NAME,'00_FALLINDEX.md'],true)){$ignored++;continue;}$oldName=(string)($file['name']??'');$name=gdOriginalCaseName($oldName);$category=gdCaseCategory($name,(string)($file['mimeType']??''));$id=(string)($file['id']??'');if($id==='')continue;$query=['addParents'=>$folders[$category],'removeParents'=>$caseId,'fields'=>'id,name,parents'];$body=$name!==$oldName?['name'=>$name]:null;gdApi('PATCH','files/'.rawurlencode($id),$query,$body);$moved++;}return['moved'=>$moved,'ignored'=>$ignored];}
function gdEnsureCaseExcelForms(string $folderId):array{$templates=gdListChildren(gdFolderId('blanco'),null,1000);$wanted=['Schlusserklärung.xlsm'=>'00_Original_Schlusserklärung.xlsm','Zahlungsbefürwortung.xlsm'=>'00_Original_Zahlungsbefürwortung.xlsm'];$result=[];foreach($wanted as$templateName=>$caseName){$existing=gdFindChildByName($folderId,$caseName);if($existing){$result[]=$existing;continue;}$template=null;foreach($templates as$item)if(strcasecmp((string)($item['name']??''),$templateName)===0){$template=$item;break;}if(!$template)apiError(503,'Excel-Originalformular nicht gefunden: '.$templateName);$result[]=gdUploadBytes($folderId,$caseName,'application/vnd.ms-excel.sheet.macroenabled.12',gdDownload((string)$template['id']));}return$result;}
function gdNormalize(string $s):string{$s=mb_strtolower(trim($s),'UTF-8');$s=strtr($s,['ä'=>'ae','ö'=>'oe','ü'=>'ue','ß'=>'ss']);return preg_replace('/[^a-z0-9]+/u',' ',$s)??'';}function gdCaseMeta(string $folderId):array{$metaFile=gdFindChildByName($folderId,CASE_META_NAME);if(!$metaFile)return[];$data=json_decode(gdDownload((string)$metaFile['id']),true);return is_array($data)?$data:[];}function gdCaseName(array $d):string{$parts=[];foreach(['schaden_nr','vn_objekt','ort']as$key){$v=trim((string)($d[$key]??''));if($v!=='')$parts[]=$v;}$name=implode(' - ',$parts);return$name!==''?mb_substr($name,0,180):'Versicherungsfall '.date('Y-m-d H-i');}function gdH(string $v):string{return htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function gdSafeName(string $v):string{$v=preg_replace('/[^A-Za-z0-9ÄÖÜäöüß._-]+/u','-',trim($v))??'';return trim($v,'-_.')?:'Fall';}
function gfOutputTitle(string $key):string{return match($key){'erstbericht'=>'Erstbericht','schadenprotokoll'=>'Schadenprotokoll','schlusserklaerung'=>'Schlusserklärung','zahlungsbefuerwortung'=>'Zahlungsbefürwortung','nachtrag_stellungnahme'=>'Nachtrag-Stellungnahme','zwischenbericht'=>'Zwischenbericht','schlussbericht'=>'Schlussbericht','vorauszahlung'=>'Vorauszahlung-Freigabe','query_form'=>'Rückfrageformular',default=>'Dokument'};}
