case'generate_documents':if($_SERVER['REQUEST_METHOD']!=='POST')apiError(405,'POST erforderlich.');$body=requestBody();$folderId=trim((string)($body['folder_id']??''));$order=is_array($body['order']??null)?$body['order']:[];$outputs=array_values(array_filter(array_map('strval',is_array($order['outputs']??null)?$order['outputs']:[])));gdAssertCaseAccess($folderId,$user);if(!$outputs)apiError(400,'Keine Dokumente ausgewählt.');$allowed=['erstbericht','schadenprotokoll','schlusserklaerung','zahlungsbefuerwortung','nachtrag_stellungnahme','zwischenbericht','schlussbericht','vorauszahlung','query_form'];foreach($outputs as$o)if(!in_array($o,$allowed,true))apiError(400,'Unbekannter Dokumenttyp: '.$o);$meta=gdCaseMeta($folderId);if(!$meta)apiError(409,'Falldaten konnten nicht geladen werden.');$userName=(string)($user['full_name']??($user['email']??'Christian Wächter'));$stamp=date('Y-m-d_His');$casePart=gdSafeName((string)($meta['schaden_nr']??'Fall'));$created=[];foreach($outputs as$key){$title=gfOutputTitle($key);$name=$casePart.'_'.gdSafeName($title).'_'.$stamp.'.doc';$file=gdUploadBytes($folderId,$name,'application/msword',gfDocumentHtml($key,$meta,$order,$userName));$fileId=(string)($file['id']??'');$created[]=['id'=>$fileId,'name'=>$file['name']??$name,'webViewLink'=>'/intern/api/case-file-browser.php?action=file&folder_id='.rawurlencode($folderId).'&file_id='.rawurlencode($fileId),'webContentLink'=>null,'type'=>$key];}$order['generated_at']=gmdate('c');$order['generated_by']=$userName;$order['generated_files']=$created;gdUploadJson($folderId,'00_Dokumentauftrag_GF.json',$order);apiJson(['ok'=>true,'created'=>$created,'count'=>count($created)]);
